'use strict';
// Original learning answers distilled from the user's resume and reviewed experience notes.
// Audio scenarios remain simulations; personal interview answers are shown separately.
window.LEARNING_UNITS = [
 {id:1,source:'统计学背景；AUMOVIO 项目跟踪；适趣 AI 多平台运营数据整理。',
 answer:'My academic background is in statistics, and I am interested in project management and data analysis in manufacturing. During my internship at AUMOVIO, I supported project tracking by keeping owners, planned dates, status updates and open risks organised. In a data operations internship, I used Python to combine order and user journey data from different platforms and prepare consistent summaries. These experiences taught me that useful analysis starts with clear definitions and ends with a clear next action. I would like to bring my analytical skills and coordination experience to a team where I can help people understand the situation and make informed decisions.',
 cn:'我的专业背景是统计学，希望从事制造业项目管理或数据分析。在 AUMOVIO 实习时，我整理责任人、计划日期、状态更新和未解决风险，支持项目跟踪。在数据运营实习中，我使用 Python 整合不同平台的订单与用户链路数据，形成口径一致的汇总。这些经历让我认识到，有用的分析始于清晰定义，也要落实到明确的下一步。我希望将分析与协调经验用于帮助团队理解现状并作出有依据的决策。',
 speaking:'用这份简历标准回答录一段60—90秒自我介绍，再脱稿回答：How did you combine data analysis with project coordination?',
 writing:'听完 W1《自我介绍》后，写80—110词的同事介绍邮件。围绕录音中的统计学背景、制造业 PM / DA 兴趣、数据来源和口径核查、责任人与下一次更新，不额外添加录音未提到的成果数字。',
 facts:['背景：statistics；方向：manufacturing project management / data analysis','方法：说明数据来源、核查定义、清楚展示关键发现','闭环：确认 action owner 和 next update'],
 email:'Subject: Introduction and how I can support the team\n\nHi team,\n\nMy academic background is in statistics, and I am interested in project management and data analysis in manufacturing. I enjoy turning complex information into a clear summary that helps a team decide what to do next. When working on an analysis, I would explain the data source, check the definitions and make the key findings easy to understand. I would also confirm the action owner and the next update so that the analysis supports a useful decision. I look forward to working with you.\n\nBest regards,\nLu Kun',
 questions:[['录音中，分析完成后还应确认什么？',['责任人与下一次更新','未经核实的节省金额','所有人已批准方案'],0,'录音以 action owner 和 next update 连接分析与行动。'],['哪项符合录音中的工作方式？',['省略数据来源','先检查定义，再清楚展示发现','把假设写成已实现成果'],1,'录音强调说明来源、核查定义并讲清关键发现。']]},
 {id:2,source:'适趣 AI：跨平台字段映射、状态口径统一、分组汇总与可复用报表流程。',
 answer:'One example is my work on multi-platform operations data. The information came from different order and user journey tables, so the same business status could be recorded in different ways. My task was to prepare a consistent basis for reporting. I used Python and pandas to map fields, match records across tables and group the results by business dimensions. I also organised the definitions for order verification, group joining and refunds. The deliverables were reusable processing scripts and reporting outputs. My contribution was the data preparation and definition work. If I repeated the task, I would confirm the status definitions with the users earlier, before building the reporting logic.',
 cn:'一个例子是我整理多平台运营数据的工作。订单和用户链路分散在不同表中，同一种业务状态可能有不同记录方式。我的任务是为报表准备一致的数据基础。我使用 Python 和 pandas 做字段映射、跨表匹配与按业务维度汇总，并整理核销、加群、退款等状态定义，交付可复用的处理脚本和报表输出。我的具体贡献是数据准备和口径整理。如果再做一次，我会在编写报表逻辑之前更早与使用者确认定义。',
 speaking:'用90秒讲清适趣数据整理经历：困难、个人任务、方法、交付物和一次反思。追问：What was your own contribution?',
 writing:'听完 W2《面试追问》后，写90—120词的练习复盘邮件，概述录音中的虚构周报案例：状态定义不一致、比对源记录、澄清定义、汇总未决问题/责任人/行动。明确这只是练习案例。',
 facts:['这是 fictional project example，不能写成真实任职成果','问题：同一状态使用不同定义','动作：比对源记录、澄清定义、一致汇总；产出：未决问题、责任人与行动'],
 email:'Subject: Practice recap: building a consistent weekly report\n\nHi coach,\n\nHere is my recap of the fictional project example in this week’s recording. The team needed a reliable weekly report, but colleagues were using different definitions for the same status. The role in the example was to compare source records, clarify the definitions and prepare a consistent summary. The resulting report showed the open questions, the responsible people and the next actions. The example helped me structure an answer around the challenge, my role, my actions and the deliverable. In an actual interview, I would use my own experience and only describe results I can explain.\n\nBest regards,\nLu Kun',
 questions:[['W2录音中的项目例子属于？',['已核实的个人成果','虚构的回答结构示例','客户正式批准记录'],1,'录音明确使用 fictional project example。'],['示例报告应呈现哪组信息？',['只有总分','没有责任人的问题列表','未决问题、责任人与下一步行动'],2,'录音中的交付物包含 open questions、responsible people、next actions。']]},
 {id:3,source:'AUMOVIO：维护跨职能项目 Tracking，整理责任人、计划日期、状态与风险。',
 answer:'At AUMOVIO, I supported project coordination by maintaining a cross-functional tracking list. I kept the responsible person, planned date, current status and open risk together so that updates could be reviewed consistently. When preparing a status update, I focused on what had changed, what was still open and who needed to provide the next confirmation. My role was to maintain and follow up on the information used for coordination. This experience taught me to separate a confirmed delay from a possible downstream impact, and to close an update with an owner and a clear next step.',
 cn:'在 AUMOVIO，我通过维护跨职能跟踪表支持项目协调，将责任人、计划日期、当前状态和未解决风险放在一起，便于一致地审阅更新。准备状态汇报时，我关注哪些事项发生变化、哪些仍未解决，以及下一步需要谁确认。我的职责是维护并跟进协调所需的信息。这段经历让我学会区分已确认延期与可能的后续影响，并在更新结束时说明责任人与下一步。',
 speaking:'先用简历标准回答说明你如何维护 Tracking，再用 W3 录音中的模拟案例做一次项目更新，明确区分两段情境。',
 writing:'根据 W3《项目周报》写100—140词状态邮件：装配计划已完成；验证节点有风险；关键部件预计晚两天；库存覆盖在核查，客户交付影响未确认；Alex 明天14:00中国标准时间确认最早交期；请求经理协调测试资源。',
 facts:['assembly plan 已完成；validation milestone at risk','部件预计延迟两天；Production Planning 正在核查库存覆盖','客户交付影响未确认；Alex 明天14:00 China Standard Time 回报最早交期','经理需在下次评审前协调 testing resource conflict'],
 email:'Subject: Sample build update: validation risk and next actions\n\nHi team,\n\nWe have completed the assembly plan for the sample build, but the validation milestone is at risk. A required component is now expected two days later than planned. Production Planning is checking inventory coverage, so the impact on customer delivery is not yet confirmed.\n\nAlex will confirm the earliest available delivery date by 14:00 China Standard Time tomorrow. We need support from the project manager to resolve the testing resource conflict before the next review. Once the delivery date and inventory coverage are confirmed, we can assess the implications for the build. I will keep the confirmed facts and open items separate in the status update.\n\nBest regards,\nLu Kun',
 questions:[['谁在何时确认最早交期？',['Alex，明天14:00中国标准时间','经理，今天下班前','采购，下周一'],0,'W3录音明确给出 Alex、tomorrow 和 two p.m. China Standard Time。'],['客户交付影响当前是什么状态？',['确定晚两天','尚未确认，库存覆盖仍在核查','已经取消交付'],1,'部件晚两天不等于客户交付已确认延期。']]},
 {id:4,source:'一知智能：将调价邮件整理成包含客户、价格类型、生效时间与来源的结构化记录。',
 answer:'In a business operations internship, I worked with historical price adjustment emails. My task was to turn information spread across messages into structured records. I organised the customer, product or route, price type, effective date and source for each record. Keeping the source was important because a reviewer might need to return to the original message and confirm the context. This experience strengthened my attention to dates, definitions and traceability. When I write a work email, I use the same approach: state the purpose, make the requested information specific and explain how the response will be used.',
 cn:'在业务运营实习中，我整理过历史调价邮件，将分散在邮件里的信息变成结构化记录，统一客户、产品或线路、价格类型、生效时间与来源。保留来源方便复核者回到原邮件确认上下文。这段经历加强了我对日期、定义和可追溯性的关注。写工作邮件时，我也采用同样的思路：说明目的、明确需要的信息，并解释回复将用于什么工作。',
 speaking:'用标准回答介绍你如何整理调价邮件，再用 W4 情境口头说明交期确认邮件的两个请求和回复期限。',
 writing:'根据 W4《邮件沟通》写100—140词给 Alex 的邮件：200件部件延迟两天；请求确认最早交期及能否分批；11月13日14:00中国标准时间前回复；将其回复与库存评估合并后向项目经理汇报。',
 facts:['收件人 Alex；200 components；供应商报告延迟两天','确认 earliest available delivery date 和 partial shipment 可行性','回复期限：13 November，14:00 China Standard Time','合并交期更新与 inventory assessment 后发给项目经理'],
 email:'Subject: Confirmation needed: delivery of 200 components\n\nHi Alex,\n\nI am writing to follow up on the delivery of 200 components. The supplier has reported a two-day delay, and we are assessing the effect on the production plan. Could you please confirm the earliest available delivery date and whether a partial shipment is possible?\n\nPlease send your update by 14:00 China Standard Time on 13 November. I will combine your update with the inventory assessment and send the project manager a summary. Your confirmation will help us assess the available delivery options using the latest information. If either point is still uncertain, please identify it clearly in your reply. Thank you for your support.\n\nBest regards,\nLu Kun',
 questions:[['W4邮件要求 Alex 确认什么？',['最终质量结论','最早交期与分批交付可行性','已经批准的加急预算'],1,'录音中有 earliest available delivery date 和 partial shipment 两个请求。'],['回复期限应写成？',['Soon','13 November，没有时间','14:00 China Standard Time on 13 November'],2,'保留日期、时点与时区，避免含糊的 soon。']]},
 {id:5,source:'适趣 AI：按日期、平台、商品等维度汇总指标并输出趋势，形成波动复核线索。',
 answer:'In a data operations internship, I prepared summaries of order and user journey metrics across platforms. I grouped the data by dimensions such as date, platform and product, and produced trend outputs for review. When a metric moved, I used the historical patterns and related indicators to identify items that needed a closer look. My task was to provide a consistent data basis and a clear review direction. I would explain a finding by stating the metric definition, the comparison period and the observed change, then describe the checks needed before drawing a conclusion about the cause.',
 cn:'在数据运营实习中，我汇总过跨平台的订单与用户链路指标，按日期、平台、商品等维度分组并输出趋势，供业务复核。出现变化时，我结合历史模式及相关指标，筛出需要进一步查看的项目。我的任务是提供一致的数据基础和清晰的复核方向。汇报发现时，我会先说明指标定义、比较区间和观测变化，再说明判断原因之前需要做哪些检查。',
 speaking:'用标准回答介绍自己的指标汇总经验，再准确复述 W5 的产出完成率、缺陷率、百分点和相对变化。',
 writing:'根据 W5《数据汇报》写100—130词分析邮件，只使用录音数字：计划1000、产出900、缺陷36、缺陷率4%、上期3%、增加1个百分点/相对约33%。提出检查产品组合与报表一致性，不加入录音未出现的交付及时率。',
 facts:['计划1000；产出900；计划完成率90%','36 / 900 = 4%；上期3%','上升1 percentage point；相对上升约33%','下一步：check product mix and reporting consistency；原因未确定'],
 email:'Subject: Production summary: output and defect rate\n\nHi manager,\n\nWe produced 900 units against a plan of 1,000, achieving 90% of the production plan. Of the 900 units produced, 36 were defective, so the defect rate was 4%. The previous rate was 3%. This means the rate increased by one percentage point, or about 33% in relative terms.\n\nThe output was below plan and the defect rate was higher than the previous rate. These figures describe the change, but they do not establish its cause. Before drawing a conclusion, we should check product mix and reporting consistency. Those checks will help us decide what further analysis is needed.\n\nBest regards,\nLu Kun',
 questions:[['W5的缺陷率是多少？',['36 / 1000 = 3.6%','36 / 900 = 4%','900 / 1000 = 90%'],1,'缺陷率分母为实际产出900，36/900=4%。'],['从3%到4%应如何表述？',['增加1个百分点，相对约33%','增加1%，相对不变','增加33个百分点'],0,'绝对变化4%−3%=1个百分点；相对变化约33%。']]},
 {id:6,source:'一知智能：Excel 与 BI 核对；从计费数量、价格版本、字段缺失等方向排查差异。',
 answer:'In a business operations internship, I compared Excel records with BI outputs used for monthly performance calculations. The challenge was that differences could come from several sources, including billed quantities, price versions and missing fields. I organised the differences and reviewed the data collection process rather than assuming one report was automatically correct. The output was a difference analysis and suggestions for improving the extraction process. This experience taught me to align definitions before explaining a gap, and to retain enough detail for another person to trace the difference back to its source.',
 cn:'在业务运营实习中，我对比过用于月度绩效核算的 Excel 记录与 BI 输出。差异可能来自计费数量、价格版本和字段缺失等多种原因。我整理差异并复核取数流程，而不是直接认定某一份报表正确，最终形成差异分析与取数流程改进建议。这让我学会先对齐定义再解释差异，并保留足够明细，方便他人追溯到源头。',
 speaking:'用标准回答讲一次报表核对经历，再根据 W6 听力提出定义、筛选、时间、粒度、重复记录和刷新时点的问题。',
 writing:'根据 W6《核实口径》写100—140词澄清邮件，逐项询问：完成订单还是全部订单、统计区间、时区、粒度、重复记录、最后刷新时间。录音没有约定回复期限，不自行填写成已约定日期。',
 facts:['先确认 metric definitions','completed orders 还是 all orders','reporting period、time zone、level of detail 是否一致','检查 duplicate records、last data refresh；对齐后再解释剩余差异'],
 email:'Subject: Clarification needed: dashboard and spreadsheet definitions\n\nHi colleague,\n\nBefore comparing the two dashboards, could we confirm the metric definitions? Does your spreadsheet include only completed orders, or does it include all orders? Are both reports using the same reporting period, time zone and level of detail?\n\nWe should also check duplicate records and the time of the last data refresh. These points may affect whether the figures are directly comparable. Once the definitions and reporting conditions are aligned, we can identify any remaining difference and explain it more clearly. Please share the relevant definitions and refresh information so that we can review the comparison on a consistent basis.\n\nBest regards,\nLu Kun',
 questions:[['比较报表之前首先应做什么？',['直接认定一张表错误','确认指标定义与比较条件','把两张表的数字平均'],1,'W6先核查定义、范围、时间与粒度。'],['哪项是 W6 要核查的信息？',['最后刷新时点与重复记录','邮件字体大小','已经确认的客户投诉金额'],0,'录音明确要求 check duplicate records 和 last data refresh。']]},
 {id:7,source:'AUMOVIO：物料状态与断点台账，归集时间节点及责任接口，支持风险跟踪。',
 answer:'At AUMOVIO, I worked on material risk tracking by organising material status, relevant dates and responsible contacts in a tracking record. The purpose was to give the team a consistent basis for follow-up and escalation. My responsibility was to keep the information structured and make open items visible. This experience showed me why supply discussions need clear ownership and current information. When reviewing options, I would distinguish a supplier indication from a confirmed commitment, list the missing information and identify which team needs to confirm it before a decision is made.',
 cn:'在 AUMOVIO，我将物料状态、相关日期和责任接口整理进跟踪记录，支持物料风险跟踪，为团队跟进和升级提供一致依据。我的职责是保持信息结构清晰并呈现未解决事项。这让我理解供应讨论为什么需要明确责任与最新信息。比较方案时，我会区分供应商意向与已确认承诺，列出缺失信息，并明确决策前需要哪个团队确认。',
 speaking:'用标准回答说明你的物料跟踪职责，再用 W7 模拟情境向经理说明两种方案及其确认条件。',
 writing:'根据 W7《供应与验证》写110—150词风险邮件：供应商可分批80件，余下120件日期未确认；方案为现有库存支持首批或申请加急；加急需要报价和批准；计划查库存、采购查供应商排程，再由经理评审。',
 facts:['可分批80件；剩余120件日期未确认','方案一：current inventory 支持 initial build；方案二：expedited shipping','加急需要 quotation and approval，不能写成已批准','Production Planning 核查库存；Procurement 核查供应商排程；经理再审议'],
 email:'Subject: Supply risk: partial shipment and delivery options\n\nHi manager,\n\nThe supplier can offer a partial shipment of 80 units, but the date for the remaining 120 units is not confirmed. We have two options to review: use current inventory for the initial build, or request expedited shipping.\n\nThe inventory option depends on available coverage. Expedited shipping would require a quotation and approval, so it should not be treated as a confirmed plan. Could Production Planning confirm inventory coverage while Procurement checks the supplier schedule? After those updates, you can review the options and make the required decision. The date for the remaining units and the approval for any expedited shipment remain open at this stage.\n\nBest regards,\nLu Kun',
 questions:[['W7供应商当前可提供多少件分批交付？',['120件，全部已确认','80件，剩余120件日期未确认','200件全部已到'],1,'录音为80件分批方案，剩余120件日期未确认。'],['加急方案目前还需要什么？',['不需要任何确认','报价与批准','先宣称客户交付已保证'],1,'Expedited shipping requires a quotation and approval。']]},
 {id:8,source:'AUMOVIO：跨职能 Tracking 与责任人/状态/计划时间维护。',
 answer:'My project coordination experience taught me to turn a discussion into a clear tracking record. At AUMOVIO, I maintained information on action owners, planned dates, status and risks for cross-functional follow-up. For me, a useful meeting summary should make it easy to see what has been agreed, what remains open and who needs to provide the next update. I would keep a proposed option separate from an approved decision. I would also ask the team to correct any missing owner or date, so that the written record supports the next round of follow-up.',
 cn:'项目协调经历让我学会将讨论转化为清晰的跟踪记录。在 AUMOVIO，我维护行动责任人、计划时间、状态和风险，支持跨职能跟进。我认为有用的会议总结应当让人清楚看到已达成什么、仍有什么未解决，以及下一次由谁更新。我会将提议与已批准决定分开，也会请团队补正缺失的责任人或日期，让书面记录支持后续跟进。',
 speaking:'用标准回答讲你如何把会议变成可跟进记录，再用 W8 录音做30秒会议收尾。',
 writing:'根据 W8《会议闭环》写90—130词会后邮件：采购确认分批排程；计划查库存覆盖；加急决定在报价前保持未决；更新行动表并按约定时间发状态。录音没有具体日期，用 agreed time，不编造时点。',
 facts:['Procurement：确认 partial shipment schedule','Production Planning：检查 inventory coverage','expedited shipping decision：报价收到前仍为 open','更新 action list，按 agreed time 发送下一次状态；请团队纠正遗漏的责任人/日期'],
 email:'Subject: Meeting follow-up: supply actions and open decision\n\nHi team,\n\nThank you for the discussion. We agreed that Procurement will confirm the partial shipment schedule, while Production Planning will check inventory coverage. The decision on expedited shipping remains open until we receive the quotation.\n\nI will update the action list and send the next status by the agreed time. The written record will keep the agreed actions separate from the open shipping decision so that we can follow up consistently. Please let me know if I have missed anything, or if an action owner or due date needs to be corrected. I will reflect the corrections in the action list.\n\nBest regards,\nLu Kun',
 questions:[['W8中哪个决定仍未解决？',['采购是否负责排程','报价收到前的加急决定','是否需要行动清单'],1,'录音说 expedited shipping remains open until we receive the quotation。'],['W8下一次状态应何时发出？',['按约定时间，录音未给出具体时点','明天14:00，所有周通用','11月13日，所有周通用'],0,'W8只说 by the agreed time，不应借用其他周的时点。']]},
 {id:9,source:'统计学背景；适趣指标汇总与趋势复核经验。此回答说明分析方法，不宣称个人完成了供应商案例中的成果。',
 answer:'My statistics background has made me careful about how a reported result is defined and measured. In operations analysis, I worked with data from different platforms and prepared consistent metric summaries. That experience is relevant when I read a manufacturing case study. I first identify the business problem and the action taken, then check the baseline, the measurement period and the metric definition. I would attribute a reported outcome to the source and keep it separate from my own interpretation. Before recommending the same approach, I would ask whether the data and operating conditions are comparable.',
 cn:'统计学背景让我关注报告结果如何定义和测量。运营分析中，我处理过不同平台的数据，并整理一致的指标汇总，这种经验也适用于阅读制造业案例。我会先找业务问题和采取的行动，再检查基线、测量期间与指标定义；引用结果时注明来源，并与个人解读分开。在推荐同一方法前，我会追问数据和业务条件是否可比。',
 speaking:'用标准回答说明你的数据经验如何帮助案例评审，再按 W9 录音用英语提出三个证据核查问题。',
 writing:'根据 W9《案例阅读》给同事写90—120词的方法邮件：找问题和行动，核查期间/基线/指标定义，注明供应商来源，区分报告结果与个人解读，列出未解问题。录音没有实际案例成效，不添加改善百分比。',
 facts:['步骤：business problem → action taken → measurement','核查 time period、baseline、metric definition','supplier claim 要标来源；区分 reported outcome 和 interpretation','录音没有给企业成效数字'],
 email:'Subject: Checks for our manufacturing case study summary\n\nHi colleague,\n\nFor our manufacturing case study summary, I suggest starting with the business problem and the action taken. We should then check how the reported result was measured, including the time period, the baseline and the metric definition.\n\nA supplier case study can provide useful context, but its claims should be attributed to the source. In the summary, we should separate the reported outcome from our interpretation and mention any important unanswered question. The recording does not provide a specific company result, so I would not add an improvement figure. These checks will help us prepare a clear and traceable summary.\n\nBest regards,\nLu Kun',
 questions:[['W9核查案例结果时应关注哪组信息？',['测量期间、基线、指标定义','只看标题','只看供应商宣传语'],0,'这三项决定报告结果如何解释和比较。'],['录音没有给实际改善数字，应如何写？',['自行添加一个合理数字','注明来源并保留未解问题，不添加数字','将供应商说法直接写成独立验证'],1,'保留出处并区分报告结果与自己的解读。']]},
 {id:10,source:'一知智能：核算差异分析；AUMOVIO：跨职能信息跟进。',
 answer:'When I discuss a recommendation, I try to connect it to the evidence and the information still needed. In my business operations work, I reviewed differences between Excel and BI outputs and considered possible issues such as quantities, price versions and missing fields. I organised the differences and proposed improvements to the extraction process. In project coordination, I also learned to make responsibilities and open items visible. If a colleague wants to act before the checks are complete, I would acknowledge the objective, explain the remaining uncertainty and propose a practical next step with a clear confirmation owner.',
 cn:'讨论建议时，我会把方案与证据、仍需确认的信息联系起来。业务运营工作中，我核对 Excel 与 BI 的差异，考虑数量、价格版本和字段缺失等可能问题，整理差异并提出取数流程改进建议。项目协调也让我学会呈现责任与未决事项。如果同事想在核查完成前行动，我会先回应目标，再说明尚存不确定性，并提出有明确确认责任人的下一步。',
 speaking:'用标准回答说明你如何基于证据提出建议，再按 W10 听力礼貌回应提前交付的要求。',
 writing:'根据 W10《建议与异议》写90—130词邮件：认可提前交付价值，但届时验证未完成；建议保留原验证窗口、优先首批；需 Testing 和 Production Planning 确认后才能承诺调整排程。',
 facts:['目标：bring delivery date forward','顾虑：validation would not be complete by then','替代：keep original validation window；prioritise first shipment','需要 Testing 和 Production Planning 确认，再承诺 revised schedule'],
 email:'Subject: Proposal: first shipment priority and validation timing\n\nHi team,\n\nI see the benefit of bringing the delivery date forward. My concern is that validation would not be complete by then. Could we keep the original validation window and prioritise the first shipment instead?\n\nThis may help us meet the most urgent need while allowing the team to complete the required checks. The proposal is intended to balance delivery urgency with the validation work that remains. We would need confirmation from Testing and Production Planning before committing to the revised schedule. Please review whether this approach is feasible so that we can discuss the next step using confirmed information.\n\nBest regards,\nLu Kun',
 questions:[['W10提出的替代方案是什么？',['跳过验证','保留原验证窗口并优先首批','立即承诺全部提前交付'],1,'录音建议 keep the original validation window and prioritise the first shipment。'],['调整排程需要谁确认？',['Testing 和 Production Planning','任意一个实习生单独批准','不需要确认'],0,'录音明确提到这两个团队的确认。']]},
 {id:11,source:'AUMOVIO 项目跟踪；适趣数据处理；一知 Excel/BI 核对。',
 answer:'I am interested in this role because it combines structured problem solving with collaboration across teams. My background in statistics helps me work carefully with definitions and evidence. At AUMOVIO, I supported project tracking by organising owners, dates, status updates and risks. In data operations, I used Python to combine records from different platforms and prepare consistent reporting outputs. I also reviewed differences between Excel and BI data in a business operations internship. For a project coordination role, I can bring clear tracking and follow-up. For a data analysis role, I can bring data preparation and reconciliation skills. I would like to understand how success is measured and how this role works with Production, Quality and Procurement.',
 cn:'我对这个岗位感兴趣，因为它结合了结构化解决问题和团队协作。统计学背景帮助我认真处理口径和证据。在 AUMOVIO，我整理责任人、日期、状态和风险，支持项目跟踪；数据运营中，我使用 Python 整合跨平台记录并准备一致的报表输出；业务运营中，我核对过 Excel 与 BI 的差异。项目协调方向我能提供清晰的跟踪与跟进，数据分析方向我能提供数据准备和核对能力。我也希望了解岗位成功标准及其与生产、质量、采购的协作方式。',
 speaking:'根据目标岗位选读标准回答中的 PM 或 DA 部分，再回答：What can you contribute in your first few months? 用已有经历支持回答。',
 writing:'根据 W11《岗位面试》的回答原则，给陪练者写90—120词准备邮件：每个例子讲实际职责、个人动作和可核实交付物；支持工作明确说 supported；准备成功标准及生产/质量/采购协作的反问。不要添加录音未提供的面试时间或录用承诺。',
 facts:['例子要说明 handled information 和 worked with people','说清 actual role、action、verifiable result / deliverable','支持流程用 supported，说明可迁移能力','反问 success measured 及 Production / Quality / Procurement 协作'],
 email:'Subject: Interview preparation: evidence and role questions\n\nHi coach,\n\nFor my interview preparation, I will choose an example that shows how I handled information and worked with other people. I will explain my actual role, the action I took and a result or deliverable I can verify.\n\nIf I only supported a process, I will describe that scope clearly and explain which skills could transfer to the position. I will also prepare questions about how success is measured in the role and how the team works with Production, Quality and Procurement. Please use these points when reviewing my answer so that the discussion stays focused on evidence and relevance.\n\nBest regards,\nLu Kun',
 questions:[['W11如何说明仅支持过的流程？',['说成独立负责全部流程','明确支持范围并说明可迁移技能','删除所有行动细节'],1,'录音强调 supported 的准确范围及技能迁移。'],['哪组面试反问符合录音？',['成功标准与跨部门协作','是否可以省略所有证据','客户已保证录用吗'],0,'录音建议问 success measured 和 Production、Quality、Procurement 协作。']]},
 {id:12,source:'统计学背景；适趣数据准备；一知差异核对；AUMOVIO 状态跟踪。',
 answer:'Across my internships, I have worked on data preparation, reconciliation and project tracking. I used Python to organise multi-platform operations data, reviewed differences between Excel and BI outputs, and maintained project status information with owners and planned dates. The common thread is making information easier to check and act on. In a new manufacturing task, I would first confirm the definitions and sources, then summarise what is known and what remains open. I would explain my finding in plain language, identify the person responsible for the next confirmation and keep a written record for follow-up. That is how I would connect my statistics training with practical team needs.',
 cn:'在几段实习中，我做过数据准备、核对与项目跟踪：使用 Python 整理多平台运营数据，复核 Excel 与 BI 差异，以及维护包含责任人与计划日期的项目状态信息。这些工作的共同点是让信息便于核查并落实到行动。面对新的制造业任务，我会先确认口径与来源，再总结已知和未决事项，用清楚的语言解释发现，明确下一次确认的责任人，并保留书面记录以便跟进。这是我把统计训练与团队实际需求连接起来的方式。',
 speaking:'用标准回答总结你能带来的工作能力，再基于 W12 模拟材料完成一次2分钟汇报和行动确认。',
 writing:'根据 W12《完整工作流》写100—140词跟进邮件：产量低于计划但缺陷率改善；尚未建立供应与质量变化之间的联系；库存覆盖未知，由计划在下次评审前确认；项目经理随后审议交付选项及审批；记录决定、更新行动表、书面总结。',
 facts:['production below plan；defect rate improved；录音无具体数字','未建立 supply issue 与 quality change 的联系','库存覆盖未确认；Production Planning 在 next review 前确认','经理审议 delivery options 和 approvals；记录决定、更新 action list、发总结'],
 email:'Subject: Follow-up: production status and delivery review\n\nHi team,\n\nHere is what we know so far: production is below plan, but the defect rate has improved. We have not established a link between the supply issue and the quality change. The remaining uncertainty is inventory coverage.\n\nProduction Planning will confirm coverage before the next review. The project manager can then review the delivery options and any approvals required. Until that information is available, the delivery review still has an open input. I will record the decision, update the action list and send a short written summary to the team. This will keep the confirmed status, open question and follow-up actions together.\n\nBest regards,\nLu Kun',
 questions:[['W12生产与质量的状态是？',['产量达标且缺陷率恶化','产量低于计划但缺陷率改善','所有指标都改善'],1,'录音同时陈述产量不足与缺陷率改善，不能混为一谈。'],['谁在下次评审前确认库存覆盖？',['Production Planning','已无需任何人确认','客户'],0,'W12明确由 Production Planning 在 next review 前确认。']]}
];
for(const unit of window.LEARNING_UNITS){
 const c=COURSES.find(c=>c.id===unit.id);
 c.sample=unit.answer;c.translation=unit.cn;c.answerSource=unit.source;c.speaking=unit.speaking;c.writing=unit.writing;
 c.questions=unit.questions.map(([q,options,a,why])=>({q:`【W${unit.id} 听力情境】${q}`,options,a,why}));
 c.steps=['先听本周录音，核对原文与事实清单。','学习本章25词，朗读基于简历的标准回答，再脱稿表达。','使用同一听力材料完成邮件，对照范文修改，最后做章节综合检测。'];
 c.checks=['能清楚说明真实个人职责','邮件与本周听力事实一致','完成章节综合检测并订正'];
}
